// Unified handbook navigation and progressive reading layout.
function detailHeading(title,label){return `<div class="article-title"><div><span class="eyebrow">${label}</span><h2>${title}</h2></div><button data-home>편람 첫 화면</button></div>`;}
function flowNav(){return '<nav class="article-nav" aria-label="점검 흐름">'+[['first','먼저 확인'],['checks','점검 순서'],['action','조치 방법'],['sources','원문 근거']].map(([id,t],j)=>`<a href="#${id}"><span>${j+1}</span> ${t}</a>`).join('')+'</nav>';}
function rows(items,kind='web-check'){return items.map((r,j)=>`<div class="${kind}">${kind==='web-check'?`<span class="step-number">${j+1}</span>`:''}<div><h3>${r[0]}</h3><p>${r[1]}</p>${articleRefs(r[2])}</div></div>`).join('');}
function sourceCollection(a,i){const ns=[...new Set([...(a.introRefs||[]),...a.criteria.flatMap(r=>r[4]),...a.checks.flatMap(r=>r[2]),...a.symptoms.flatMap(r=>r[3]),...a.maintenance.flatMap(r=>r[2]),...a.cases.flatMap(r=>r[2])])].sort((a,b)=>a-b);return `<p class="article-note">한국지역난방공사 · 열사용시설 관리업무 편람 (2025.10)</p>${articleRefs(ns)}<p><button data-original="${i}">이 항목의 원문 목록</button></p><details class="reference-fold"><summary>그림·계통도 ${a.figures.length}개</summary><div class="article-figures">${a.figures.map(r=>`<button class="figure-card" data-page="${r[1]}"><img src="pages/${r[1]}.webp" loading="lazy" alt="${r[0]} 원문 ${r[1]}쪽"><strong>${r[0]}</strong><span>원문 ${r[1]}쪽 열기</span></button>`).join('')}</div></details>${a.topics?.length?`<details class="reference-fold"><summary>세부 항목 찾아보기</summary><div class="topic-index">${a.topics.map(t=>`<button data-page="${t[1]}"><strong>${t[0]}</strong><span>${t[1]}–${t[2]}쪽</span></button>`).join('')}</div></details>`:''}`;}
showArticle=function(i){const a=ARTICLES[i];renderNav(Number(i));$('query').value='';$('content').innerHTML=`<article class="equipment-article">${detailHeading(a.title,'설비·업무별 편람')}${flowNav()}`+articleBlock('first','1. 먼저 확인할 사항',`<p>${a.intro}</p><div class="symptom-table">${a.symptoms.map(r=>`<div><h3>${r[0]}</h3><p>${r[1]}</p>${r[2]===null?'':`<button data-guide="${r[2]}">이 증상의 점검 안내</button>`}${articleRefs(r[3])}</div>`).join('')}</div><details class="reference-fold"><summary>정상 상태·판단 기준 확인</summary><p class="article-note">현장 설계조건과 제작사 기준을 함께 비교하세요. 사례값은 공통 설정값이 아닙니다.</p>${a.criteria.map(r=>`<div class="criterion"><div class="criterion-label"><strong>${r[0]}</strong><span class="value-type">${r[2]}</span></div><div><b class="criterion-value">${r[1]}</b><p>${r[3]}</p>${articleRefs(r[4])}</div></div>`).join('')}</details>`)+articleBlock('checks','2. 점검 순서',(['0','1','4'].includes(String(i))?measurementEntry(({0:'pdcv',1:'he',4:'pump'})[i]):'')+rows(a.checks))+articleBlock('action','3. 조치·관리 방법',rows(a.maintenance,'maintenance-item')+`<details class="reference-fold"><summary>${Number(i)>=10?'참고·비교 항목':'진단사례'} 보기</summary>${rows(a.cases,'case-item')}</details>`)+articleBlock('sources','4. 원문 근거',sourceCollection(a,i))+'</article>';};
showGuide=function(i){const g=GUIDES[i];renderNav();$('content').innerHTML=`<article class="guide">${detailHeading(g.title,'증상별 점검 안내')}${flowNav()}`+articleBlock('first','1. 먼저 확인할 사항',`<p>${g.sub}</p><p class="article-note">여러 원인이 함께 나타날 수 있습니다. 현장 설계조건과 운전기록을 함께 비교하세요.</p>${TROUBLESHOOT[i]?`<div class="wizard-entry"><div><strong>질문에 답하며 점검 항목 좁히기</strong><p>현재 상태에 맞는 확인 순서와 원문을 안내합니다.</p></div><button data-wizard="${i}">질문형 점검 시작</button></div>`:''}`)+articleBlock('checks','2. 점검 순서',`<ol class="check-steps">${g.steps.map((r,j)=>`<li><span class="step-number">${j+1}</span><div><h3>${r[0]}</h3><p>${r[1]}</p>${articleRefs(r[2])}</div></li>`).join('')}</ol>`)+articleBlock('action','3. 조치 방법',`<div class="pro-box"><h3>전문 점검·조치</h3><p>${g.pro}</p></div>`)+articleBlock('sources','4. 원문 근거',`<p class="article-note">한국지역난방공사 · 열사용시설 관리업무 편람 (2025.10)</p>${articleRefs(g.refs)}`)+'</article>';};
home=function(){renderNav();$('query').value='';$('content').innerHTML=`<section class="home-symptoms"><div class="section-heading"><div><span class="eyebrow">증상으로 찾기</span><h2>어떤 문제가 있나요?</h2></div><span class="count">8가지 주요 증상</span></div><div class="quick-symptoms">${GUIDES.map((g,i)=>`<button data-guide="${i}"><strong>${g.title}</strong><span>${g.sub}</span><b>점검 순서 보기</b></button>`).join('')}</div></section><section class="equipment-finder"><div><span class="eyebrow">설비·업무로 찾기</span><h2>설비 이름을 알고 있나요?</h2><p>설비를 선택하면 확인사항과 점검 순서를 볼 수 있습니다.</p></div><label for="equipment-select" class="sr">설비·업무 선택</label><select id="equipment-select"><option value="">설비·업무 선택</option>${SECTIONS.map((s,i)=>`<option value="${i}">${s[0]}</option>`).join('')}</select><button id="equipment-go">편람 보기</button></section>`;$('equipment-go').onclick=()=>{const v=$('equipment-select').value;if(v!=='')section(Number(v));else $('equipment-select').focus();};};
$('home').onclick=home;
const side=$('equipment-menu');if(side){const mq=matchMedia('(max-width: 900px)');const apply=()=>side.open=!mq.matches;apply();mq.addEventListener('change',apply);document.addEventListener('click',e=>{if(mq.matches&&e.target.closest('[data-section], [data-home]'))side.open=false;});}
home();
// On detail pages the search is a compact optional tool; home keeps it expanded.
const searchArea=document.querySelector('.search-area');
if(searchArea){
 const searchDetails=document.createElement('details');searchDetails.id='handbook-search';searchDetails.className='handbook-search';searchDetails.open=true;searchDetails.dataset.context='home';
 const searchToggle=document.createElement('summary');searchToggle.textContent=' 편람 검색 열기·접기';searchDetails.append(searchToggle);searchArea.before(searchDetails);searchDetails.append(searchArea);
 const contentChanges=new MutationObserver(()=>{const detail=!!$('content').querySelector('.equipment-article,.guide,.wizard');searchDetails.dataset.context=detail?'detail':'home';searchDetails.open=!detail;});contentChanges.observe($('content'),{childList:true});
}
